## Configuring environment variables
Create a `.env` file in your project root and add your Ahrefs API credentials:
```
AHREFS_CLIENT_ID=your_client_id
AHREFS_CLIENT_SECRET=your_client_secret
REDIRECT_URI=http://localhost:3000/callback
```
Now, let's create a simple Express server to handle our auth flow:
```
require('dotenv').config();
const express = require('express');
const axios = require('axios');
const app = express();
const port = 3000;
app.get('/auth', (req, res) => {
const authUrl = `https://app.ahrefs.com/api/auth?client_id=${process.env.AHREFS_CLIENT_ID}&redirect_uri=${process.env.REDIRECT_URI}&response_type=code`;
res.redirect(authUrl);
});
app.get('/callback', async (req, res) => {
const { code } = req.query;
try {
const response = await axios.post('https://app.ahrefs.com/api/token', {
client_id: process.env.AHREFS_CLIENT_ID,
client_secret: process.env.AHREFS_CLIENT_SECRET,
code,
grant_type: 'authorization_code',
redirect_uri: process.env.REDIRECT_URI
});
const { access_token, refresh_token } = response.data;
// Store these tokens securely (more on this later)
res.send('Authorization successful!');
} catch (error) {
